def get_prime_factorization(n):
    """Returns list of (prime, exponent) pairs for prime factorization of n."""
    factors = {}
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            factors[i] = count
    if n > 1:
        factors[n] = 1
    return [i for i in factors]

