    def solve(n, m, grid):
        count = 0

        # Type 1: axis-aligned squares
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '1':
                    continue

                max_k = min(n - r - 1, m - c - 1) + 2
                if max_k < 2:
                    continue

                for k in range(2, max_k + 1):
                    r1, c1 = r, c
                    r2, c2 = r + k - 1, c + k - 1

                    if r2 >= n or c2 >= m:
                        break

                    # Check top row
                    top_valid = all(grid[r1][c] == '1' for c in range(c1, c2 + 1))
                    if not top_valid:
                        break

                    # Check bottom row
                    bottom_valid = all(grid[r2][c] == '1' for c in range(c1, c2 + 1))
                    if not bottom_valid:
                        continue

                    # Check left column
                    left_valid = all(grid[r][c1] == '1' for r in range(r1 + 1, r2))
                    if not left_valid:
                        continue

                    # Check right column
                    right_valid = all(grid[r][c2] == '1' for r in range(r1 + 1, r2))
                    if not right_valid:
                        continue

                    # Check interior is all 0s
                    interior_valid = True
                    for ir in range(r1 + 1, r2):
                        for ic in range(c1 + 1, c2):
                            if grid[ir][ic] == '1':
                                interior_valid = False
                                break
                        if not interior_valid:
                            break

                    if interior_valid:
                        count += 1

        # Type 2: diagonal squares 
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '1':
                    continue

                max_k = min(r, c, n - 1 - r, m - 1 - c) + 2
                if max_k < 2:
                    continue

                for k in range(2, max_k + 1):
                    # Top vertex
                    rt = r - k
                    ct = c

                    # Right vertex  
                    rr = r
                    cr = c + k

                    # Bottom vertex
                    rb = r + k
                    cb = c

                    # Left vertex
                    rl = r
                    cl = c - k

                    # Check all vertices within bounds and are '1'
                    if rt < 0 or rb >= n or cl < 0 or cr >= m:
                        continue
                    if grid[rt][ct] != '1' or grid[rr][cr] != '1' or \
                       grid[rb][cb] != '1' or grid[rl][cl] != '1':
                        continue

                    # Check diagonal edges for '1's
                    edges_valid = True

                    # Top to right (diagonal)
                    for i in range(k):
                        pr = rt + i
                        pc = ct + i
                        if grid[pr][pc] != '1':
                            edges_valid = False
                            break

                    if not edges_valid:
                        continue

                    # Right to bottom (diagonal)
                    for i in range(k):
                        pr = rr + i
                        pc = cr - i
                        if grid[pr][pc] != '1':
                            edges_valid = False
                            break

                    if not edges_valid:
                        continue

                    # Bottom to left (diagonal)
                    for i in range(k):
                        pr = rb - i
                        pc = cb - i
                        if grid[pr][pc] != '1':
                            edges_valid = False
                            break

                    if not edges_valid:
                        continue

                    # Left to top (diagonal)
                    for i in range(k):
                        pr = rl - i
                        pc = cl + i
                        if grid[pr][pc] != '1':
                            edges_valid = False
                            break

                    if not edges_valid:
                        continue

                    count += 1

        return str(count)

