def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    graph = [[] for _ in range(n + 1)]

    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append({'u': u, 'v': v, 'w': w, 'id': i + 1})
        graph[u].append((v, i + 1))
        graph[v].append((u, i + 1))

    def bfs_reach(start, end, blocked):
        visited = [False] * (n + 1)
        queue = [start]
        visited[start] = True

        while queue:
            curr = queue.pop(0)
            if curr == end:
                return True
            for neighbor, eid in graph[curr]:
                if not visited[neighbor] and eid not in blocked:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited[end]

    # Check if already disconnected (0 edges)
    if not bfs_reach(s, t, set()):
        return "0\n0\n"

    # Try removing 1 edge
    for i in range(m):
        if not bfs_reach(s, t, {edges[i]['id']}):
            return f"{edges[i]['w']}\n1\n{edges[i]['id']}\n"

    # Try removing 2 edges - focus on edges on reachable paths from s
    reachable = set()
    queue = [s]
    while queue and len(reachable) < 2000:
        node = queue.pop(0)
        reachable.add(node)
        for nxt, _ in graph[node]:
            if nxt not in reachable:
                reachable.add(nxt)
                queue.append(nxt)

    # Get candidate edges near s or t
    candidates = {e['id'] for e in edges if e['u'] in reachable or e['v'] in reachable}
    cand_list = [edges[i - 1] for i in sorted(candidates)[:min(3000, m)]]

    best = (float('inf'), None)

    for i in range(min(3000, len(cand_list))):
        for j in range(i + 1, min(3000, len(cand_list))):
            if not bfs_reach(s, t, {cand_list[i]['id'], cand_list[j]['id']}):
                cost = cand_list[i]['w'] + cand_list[j]['w']
                pair = tuple(sorted([cand_list[i]['id'], cand_list[j]['id']]))
                if cost < best[0]:
                    best = (cost, pair)

    if best[1]:
        return f"{best[0]}\n2\n{' '.join(map(str, best[1]))}\n"

    return "-1\n"

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        t = parts[0]
        x_prime = parts[1]
        y = parts[2]
        x = x_prime / 100000.0
        operations.append((t, x, y))

    earliest = [-1] * (m + 1)
    current_reachable = {0}

    for time_step, (t, x, y) in enumerate(operations, 1):
        # Calculate all new reachable values from the current operation
        new_reachable = set()

        if t == 1:
            # Type 1: k := ceil(k + x) applied a times
            # If we apply it a times, result is ceil(k + a*x)
            for v in current_reachable:
                for a in range(y + 1):
                    val = math.ceil(v + a * x)
                    if val <= m:
                        new_reachable.add(val)
        else:
            # Type 2: k := ceil(k * x) applied a times
            for v in current_reachable:
                for a in range(y + 1):
                    if a == 0:
                        val = v
                    else:
                        current_val = v
                        for _ in range(a):
                            current_val = math.ceil(current_val * x)
                        val = current_val
                    if val <= m:
                        new_reachable.add(val)

        # Update reachable set with new values
        current_reachable.update(new_reachable)

        # Record the earliest time-step for newly reachable values
        for val in new_reachable:
            if earliest[val] == -1:
                earliest[val] = time_step

    # Format output as space-separated values for 1 to m
    return ' '.join(map(str, earliest[1:m+1]))

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return '0'

    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n = len(s1)
    m = len(s2)
    v = len(virus)

    if n == 0 or m == 0 or v == 0:
        return '0'

    # KMP preprocessing for the virus
    pi = [0] * v
    for i in range(1, v):
        j = pi[i - 1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build transition table for virus matching
    # trans[state][char_code] = new_state
    trans = [[0] * 26 for _ in range(v)]
    for state in range(v):
        for char_code in range(26):
            c = chr(ord('A') + char_code)
            j = state
            while j > 0 and c != virus[j]:
                j = pi[j - 1]
            if c == virus[j]:
                j += 1
            trans[state][ord(c) - ord('A')] = j

    # DP: dp[i][j][state] = length of LCS ending at s1[i], s2[j] with virus state
    INF = -1
    dp = [[[INF] * v for _ in range(m + 1)] for _ in range(n + 1)]

    # parent[i][j][state] = (prev_i, prev_j, prev_state, char_added_or_0)
    parent = [[[[[-1]] * v for _ in range(m + 1)] for _ in range(n + 1)]]

    # Fill DP
    for i in range(n + 1):
        for j in range(m + 1):
            for state in range(v):
                # Option 1: Skip s1[i] (or stay at same)
                if dp[i][j][state] == INF and i - 1 >= 0:
                    dp[i][j][state] = max(dp[i][j][state], dp[i-1][j][state])
                    if parent[i][j][state][0] == -1 and parent[i-1][j][state][0] != -1:
                        parent[i][j][state] = parent[i-1][j][state]

                # Option 2: Skip s2[j] (or stay at same)
                if dp[i][j][state] == INF and j - 1 >= 0:
                    dp[i][j][state] = max(dp[i][j][state], dp[i][j-1][state])
                    if parent[i][j][state][0] == -1 and parent[i][j-1][state][0] != -1:
                        parent[i][j][state] = parent[i][j-1][state]

                # Option 3: Match s1[i-1] and s2[j-1]
                if i - 1 >= 0 and j - 1 >= 0 and s1[i-1] == s2[j-1]:
                    c_code = ord(s1[i-1]) - ord('A')
                    new_state = trans[state][c_code]
                    if new_state < v:
                        new_len = dp[i-1][j-1][state] + 1
                        if new_len > dp[i][j][new_state]:
                            dp[i][j][new_state] = new_len
                            parent[i][j][new_state] = (i-1, j-1, state, 1)

    # Find best final state
    best_len = 0
    best_i, best_j, best_state = 0, 0, 0
    for state in range(v):
        if dp[n][m][state] > best_len:
            best_len = dp[n][m][state]
            best_i, best_j, best_state = n, m, state

    # If max length is 0, return '0'
    if best_len == 0:
        return '0'

    # Reconstruct solution
    result = []
    i, j, state = best_i, best_j, best_state

    while i > 0 and j > 0:
        p = parent[i][j][state]
        if p[3] == 1:
            # We matched a character
            result.append(s1[i-1])
            i, j, state = p[0], p[1], p[2]
        elif p[0] == i - 1:
            # We skipped s1
            i = p[0]
        elif p[1] == j - 1:
            # We skipped s2
            j = p[1]
        else:
            break

    # Reverse to get correct order
    result.reverse()
    return ''.join(result)

