def grundy(n, cache, k):
    if n in cache:
        return cache[n]

    # Option 1: Remove 1 cow (state becomes n-1)
    mex_set = {grundy(n - 1, cache, k)}

    # Option 2: If n is even, split into k piles of size n/2
    if n % 2 == 0:
        g_half = grundy(n // 2, cache, k)
        # XOR of k identical values is g_half if k is odd, 0 if k is even
        if k % 2 == 0:
            mex_set.add(0)
        else:
            mex_set.add(g_half)

    # Compute mex (Minimum Excluded value)
    result = 0
    while result in mex_set:
        result += 1
    cache[n] = result
    return result

