def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Compute prefix sums
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + a[i]

    # Function to compute weakness for a given x
    def f(x):
        mx = P[0] - 0 * x
        mn = P[0]
        for i in range(1, n + 1):
            val = P[i] - i * x
            if val > mx:
                mx = val
            if val < mn:
                mn = val
        return mx - mn

    # Ternary search for optimal x
    low, high = -2e7, 2e7  # bounded by reasonable range
    for _ in range(100):
        mid1 = low + (high - low) / 3
        mid2 = high - (high - low) / 3
        if f(mid1) < f(mid2):
            high = mid2
        else:
            low = mid1

    # Evaluate at optimal x
    return f(low + (high - low) / 3)

