            break

        n, m = map(int, lines[idx].split())
        idx += 1

        colors = []
        for _ in range(n):
            colors.append(lines[idx])
            idx += 1

        dirs = []
        for _ in range(n):
            dirs.append(lines[idx])
            idx += 1

        # Build next cell map
        nxt = [[0]*m for _ in range(n)]
        for r in range(n):
            for c in range(m):
                d = dirs[r][c]
                if d == 'U':
                    nxt[r][c] = (r-1, c)
                elif d == 'D':
                    nxt[r][c] = (r+1, c)
                elif d == 'L':
                    nxt[r][c] = (r, c-1)
                elif d == 'R':
                    nxt[r][c] = (r, c+1)

        # Flatten
        cell_to_id = {}
        for r in range(n):
            for c in range(m):
                cell_to_id[(r,c)] = r*m + c

        adj = [0] * (n*m)
        for r in range(n):
            for c in range(m):
                nr, nc = nxt[r][c]
                adj[cell_to_id[(r,c)]] = cell_to_id[(nr,nc)]

        # Find cycles
        vis = set()
        cycle_data = []
        cycle_pos = {}

        for start in range(n*m):
            if start in vis:
                continue

            path = []
            curr = start
            while curr not in vis:
                vis.add(curr)
                path.append(curr)
                curr = adj[curr]

            if curr in path:
                cycle_start = path.index(curr)
                cycle_len = len(path) - cycle_start
                cid = len(cycle_data)
                cycle_data.append(cycle_len)
                for k in range(cycle_start, len(path)):
                    pos = k - cycle_start
                    cycle_pos[path[k]] = (cid, pos)

        # Handle remaining
        for i in range(n*m):
            if i in cycle_pos:
                continue

            # Find if leads to a cycle
            curr = i
            path = [i]
            while curr not in cycle_pos and curr not in vis:
                vis.add(curr)
                path.append(curr)
                curr = adj[curr]

            if curr in cycle_pos:
                cid, pos = cycle_pos[curr]
                for node in path:
                    cycle_pos[node] = (cid, pos)

        # Max robots = unique cycle positions
        ans_map = set()
        for i in range(n*m):
            ans_map.add(cycle_pos.get(i, (-1, -1)))
        max_rotors = len(ans_map)

        # Max black cells
        black_count = [0] * (n*m)
        for r in range(n):
            for c in range(m):
                if colors[r][c] == '0':
                    black_count[cell_to_id[(r,c)]] = 1

        max_black = 0
        for (cid, pos) in ans_map:
            count = 0
            for i in range(n*m):
                if cycle_pos.get(i) == (cid, pos):
                    count += black_count[i]
            if count > max_black:
                max_black = count

        results.append("{} {}\n".format(max_rotors, max_black))

    return ''.join(results)

