                else:
                    ops_needed = abs(result[i]) // x

                if ops_needed <= ops_left:
                    sign = 1 if result[i] > 0 else -1 if result[i] < 0 else 1
                    result[i] -= ops_needed * x * sign
                    ops_left -= ops_needed
                    has_zero = (result[i] == 0)
                    break

    # If still no zero and we have ops, try to maximize negative product
    if not has_zero:
        # Check if we should make all elements negative or have mixed signs
        neg_count = sum(1 for r in result if r < 0)
        pos_count = sum(1 for r in result if r > 0)

        # Strategy: minimize absolute values or arrange for better product
