    # Read grid rows
    grid = []
    idx = 2
    for i in range(n):
        if idx >= len(parts):
            break
        grid.append(list(parts[idx]))
        idx += 1

    # Function to check if a cell has conflicts with any other same-colored neighbor
    def has_conflict(i, j):
        color = grid[i][j]
        # Check all 8 neighbors (including diagonals)
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    if grid[ni][nj] == color:
                        return True
        return False

    # Check if input already contains conflicts
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                if has_conflict(i, j):
                    return "0"

    # Fill in 0s using a pattern based on 2x2 quadrant blocks
    # Pattern ensures no adjacent (including diagonal) cells have same color
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '0':
                # Determine quadrant pattern (4 positions in 2x2 block)
                q = (i // 2) % 2 * 2 + (j // 2) % 2
                if q == 0:
                    grid[i][j] = '1'
                elif q == 1:
                    grid[i][j] = '3'
                elif q == 2:
                    grid[i][j] = '4'
                elif q == 3:
                    grid[i][j] = '2'

    # Convert to string output
    result = []
    for i in range(n):
        result.append(''.join(grid[i]))

    return '\n'.join(result)


