def solution(input_string):
    # Parse input
    lines = input_string.strip().split('\n')
    if not lines:
        return 'NO'

    try:
        parts = lines[0].split()
        N, M = int(parts[0]), int(parts[1])
    except:
        return 'NO'

    edges = []
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 3:
            u, v, c = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((u, v, c))

    # Handle case with no constraints
    if M == 0:
        return 'YES\n' + ' '.join('0.0' for _ in range(N))

    # Build augmented matrix [A | b]
    # Each edge (u, v, c) gives equation: x[u-1] + x[v-1] = c
    num_eq = M
    num_vars = N

    matrix = [[0.0] * (num_vars + 1) for _ in range(num_eq)]
    for i, (u, v, c) in enumerate(edges):
        matrix[i][u-1] = 1.0
        matrix[i][v-1] = 1.0
        matrix[i][num_vars] = float(c)

    # Gaussian-Jordan elimination with partial pivoting
    pivot_row_count = 0
    pivot_col_map = {}

    for col in range(num_vars):
        # Find pivot row with largest absolute value
        best_row = -1
        best_val = 0.0
        for r in range(pivot_row_count, num_eq):
            if abs(matrix[r][col]) > best_val:
                best_val = abs(matrix[r][col])
                best_row = r

        if best_val < 1e-12:
            continue  # Column is dependent

        # Swap rows
        if best_row != pivot_row_count:
            matrix[pivot_row_count], matrix[best_row] = matrix[best_row], matrix[pivot_row_count]

        pivot_col_map[col] = pivot_row_count

        # Normalize pivot row
        pivot = matrix[pivot_row_count][col]
        for c in range(col, num_vars + 1):
            matrix[pivot_row_count][c] /= pivot

        # Eliminate column from all other rows
        for r in range(num_eq):
            if r != pivot_row_count:
                factor = matrix[r][col]
                if abs(factor) > 1e-12:
                    for c in range(col, num_vars + 1):
                        matrix[r][c] -= factor * matrix[pivot_row_count][c]

        pivot_row_count += 1

    # Check for inconsistency
    for r in range(pivot_row_count, num_eq):
        if abs(matrix[r][num_vars]) > 1e-9:
            return 'NO'

    # Extract solution (free variables set to 0)
    ans = [0.0] * num_vars
    for r in range(pivot_row_count - 1, -1, -1):
        col = pivot_col_map[r]
        val = matrix[r][num_vars]
        for c in range(col + 1, num_vars):
            val -= matrix[r][c] * ans[c]
        ans[col] = val

    return 'YES\n' + ' '.join(str(x) for x in ans)

