def multiply(A, B, mod):
    n = len(A)
    m = len(B)
    k = len(B[0])
    C = [[0]*k for _ in range(n)]
    for i in range(n):
        for j in range(k):
            for l in range(m):
                C[i][j] = (C[i][j] + A[i][l] * B[l][j]) % mod
    return C

def power(A, p, mod):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p > 0:
        if p % 2 == 1:
            result = multiply(result, base, mod)
        base = multiply(base, base, mod)
        p //= 2
    return result

