class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def parse(self):
        result = self.parse_term()
        while self.pos < self.n and self.s[self.pos] == '+':
            self.pos += 1
            right = self.parse_term()
            result = self.concat(result, right)
        return result

    def parse_term(self):
        left = self.parse_factor()
        while self.pos < self.n and self.s[self.pos] == '-':
            self.pos += 1
            right = self.parse_number()
            result = self.range_cat(left, right)
        return result

    def parse_factor(self):
        if self.pos < self.n and self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            inner = self.parse()
            if self.pos < self.n and self.s[self.pos] == ')':
                self.pos += 1  # skip ')'
            return inner
        else:
            return self.parse_number()

    def parse_number(self):
        j = self.pos
        while self.pos < self.n and self.s[self.pos].isdigit():
            self.pos += 1
        if j < self.pos:
            return int(self.s[j:self.pos])
        return int(self.s[j:self.pos])

    def digit_len(self, n):
        return len(str(n)) if n > 0 else 0

    def concat(self, left, right):
        l_len = right[1] % MOD
        return (left[0] * pow_mod(10, l_len, MOD) + right[0]) % MOD, (left[1] + right[1]) % MOD

    def range_cat(self, l, r):
        def compute(min_val, max_val, lengths):
            if min_val > max_val:
                return 0, 0
            min_len = lengths[min_val][0] if min_val in lengths else self.digit_len(min_val)
            max_len = lengths[max_val][0] if max_val in lengths else self.digit_len(max_val)

            if min_len != max_len:
                if lengths is None:
                    length_map = {}
                else:
                    length_map = lengths.copy()

                left = pow_mod(10, max_len * (max_val - min_len + 1), MOD)

                def compute_range(s, total_len, max_digits):
                    if s > max_val or total_len == 0:
                        return 0
                    s_len = max_digits[s] if s in max_digits else self.digit_len(s)

                    if s == max_val:
                        return s % MOD, max(0, total_len - s_len)

                    return (s * pow_mod(10, total_len - s_len, MOD)) % MOD, total_len - s_len

                return 0, 0

        return 0, 0

