def dfs_traverse(adj, start):
    """Simple DFS traversal for path building."""
    path = [start]
    visited = {start}

    curr = start
    for _ in range(2000):
        found = -1
        for i, nxt in enumerate(adj[curr]):
            if nxt not in visited:
                visited.add(nxt)
                path.append(nxt)
                curr = nxt
                found = i
                break

        if found == -1:
            break

    return path

