def is_stable(matching, n, matrix):
    """Check if the matching is stable"""
    # Everyone must have a match
    if any(m == -1 for m in matching):
        return False

    for i in range(n):
        partner = matching[i]
        my_cost = matrix[i][partner]

        # If my_cost is inf, consider it unsolvable
        if my_cost == float('inf'):
            return False

        # Check all other cities
        for j in range(n):
            if j == i:
                continue
            if j == partner:
                continue

            other_partner = matching[j]

            # Can j exist without a partner? 
            if other_partner == -1:
                continue

            # Cost for i to connect to j
            cost_ij = matrix[i][j]
            cost_i_current = my_cost

            # Cost for j to connect to i
            cost_ji = matrix[j][i]
            cost_j_current = matrix[j][other_partner]

            # If both prefer each other, unstable
            if cost_ij < cost_i_current and cost_ji < cost_j_current:
                return False

    return True


