    t = get_int()
    results = []

    for _ in range(t):
        n = read_ints()[0]
        m = read_ints()[1]

        matrix = []
        for _ in range(n):
            matrix.append(read_ints())

        operations = read_line()
        operations = list(operations[:m])  # Take exactly m operations

        # Simulate operations
        cols = n

        # Helper to compute inverse permutation
        def inverse_perm(perm):
            inv = [0] * len(perm)
            for i, v in enumerate(perm):
                inv[v - 1] = i + 1  # Convert to 1-indexed
            return inv

        for op in operations:
            if op == 'R':
                # Shift columns right: col j goes to col (j+1)%n
                # a[i][j] = a[i][(j-2)%n + 1] => element at col j-1 moves to col j
                # Actually: a_{i,j} <- a_{i, ((j-2)mod n) + 1}
                # So new[j] = old[(j-2)%n + 1] = old[(j-1-1)%n+1] = old[(j-1)%n + 1]
                # More simply: right shift: element at col j goes to col (j+1)%n
                # So new[col] = old[(col - 1) % n]
                for r in range(n):
                    matrix[r] = matrix[r][-1] + matrix[r][:-1]

            elif op == 'L':
                # Shift columns left: col j goes to col (j-1)%n
                for r in range(n):
                    matrix[r] = matrix[r][1:] + matrix[r][:1]

            elif op == 'D':
                # Shift rows down: row i goes to row (i+1)%n
                # So new[i] = old[(i-1)%n]
                rows = [list(row) for row in matrix]
                new_rows = [rows[-1]] + rows[:-1]
                matrix = new_rows

            elif op == 'U':
                # Shift rows up: row i goes to row (i-1)%n
                # So new[i] = old[i+1]
                for r in range(n):
                    temp = [list(row) for row in matrix]
                    matrix[r] = temp[(r + 1) % n]

            elif op == 'I':
                # For each row, replace with inverse permutation
                for r in range(n):
                    row = matrix[r]
                    inv_row = inverse_perm(list(row))
                    matrix[r] = inv_row

            elif op == 'C':
                # For each column, replace with inverse permutation
                # First collect columns
                transposed = [[matrix[r][c] for r in range(n)] for c in range(n)]
                for c in range(n):
                    col = transposed[c]
                    inv_col = inverse_perm(list(col))
                    transposed[c] = inv_col
                # Convert back
                matrix = [list(transposed[r]) for r in range(n)]

        # Build output
        output_lines = []
        for row in matrix:
            output_lines.append(' '.join(map(str, row)))

        results.append('\n'.join(output_lines))

    return '\n\n'.join(results)

