        """Normalize edge to always have a < b, then adjust if interval is too long"""
        if a > b:
            a, b = b, a

        half = n // 2 + 1
        diff = b - a
        if diff > half:
            # The other way around the circle is shorter
            return (a, n - a + 1 - diff + 1 - b)
        return (a, b)

    def crosses(e1, e2):
        """Check if two edges cross when both placed inside or both placed outside"""
        u1, v1 = normalize(e1[0], e1[1])
        u2, v2 = normalize(e2[0], e2[1])

        # Check if intervals interleave (a1 < a2 < b1 < b2 type)
        return (u1 < u2 < v1 < v2) or (u2 < u1 < v2 < v1) or \
               (u1 < u2 and v2 < v1) or (u2 < u1 and v1 < v2)

    # Simple 2-SAT style backtracking with pruning
    def can_solve(idx, inside, outside):
        # Check assignments for both current edge choices
        candidates = []

        for i in range(idx):
            if inside:
                if edges[i] in inside and crosses(edges[i], edges[idx]):
                    return False
            if outside:
                if edges[i] in outside and crosses(edges[i], edges[idx]):
                    return False

        # Try assigning current edge as inside or outside
        for choice in [0, 1]:
            if choice == 0:  # outside
                valid = True
                for i in range(idx):
                    if inside:
                        if edges[i] in inside and crosses(edges[i], edges[idx]):
                            valid = False
                            break
                if valid and can_solve(idx + 1, True, False):
                    return True
            else:  # inside
                valid = True
                for i in range(idx):
