import sys

def solution(input_str):
    n, p, l, r = map(int, input_str.split())

    result = 0

    for a in range(n + 1):
        for b in range(n + 1 - a):
            if a < b:
                continue

            if l <= a - b <= r:
                c = n - a - b

                # Number of valid sequences of a A's and b B's where at every point
                # prefix count of A >= prefix count of B
                # Using reflection principle: C(a+b, b) - C(a+b, b-1)
                # If b=0, the result is 1 (all A's, only one valid sequence)
                val_ab = math.comb(a + b, b) - math.comb(a + b, b - 1)

                # Number of ways to interleave c C's into the sequence
                ways = math.comb(a + b + c, c)

                result = (result + val_ab * ways) % p

    return str(result)

