    grid = [['.' for _ in range(m)] for _ in range(n)]

    # All 4 T-shapes (relative coordinates from top-left placement position)
    shapes = [
        # T pointing down (3 cells horizontal top, center column extending)
        [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)],
        # T pointing right (3 cells vertical left, center column extending right)
        [(0, 0), (1, 0), (2, 0), (1, 1), (1, 2)],
        # T pointing up (3 cells vertical right, center column extending up)
        [(0, 2), (0, 1), (0, 0), (1, 1), (2, 1)],
        # T pointing left (3 cells vertical right-centered, extends left)
        [(0, 1), (0, 0), (0, 2), (1, 1), (2, 1)],
    ]

    placed = []
    placement_count = 0

    def can_place(start_r, start_c, shape):
        for dr, dc in shape:
            nr, nc = start_r + dr, start_c + dc
            if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] != '.':
                return False
        return True

    def place(start_r, start_c, shape, letter):
        for dr, dc in shape:
            grid[start_r + dr][start_c + dc] = letter
        placed.append((letter, start_r, start_c, shape))
        return True

    def remove(start_r, start_c, shape):
        for dr, dc in shape:
            grid[start_r + dr][start_c + dc] = '.'
        placed.pop()

    def backtrack():
        max_so_far = placement_count

        # Calculate how many more could fit (greedy upper bound)
        empty_cells = sum(row.count('.') for row in grid)
        estimated_remaining = empty_cells // 5
        if placement_count + estimated_remaining <= max_so_far:
            return

        # Try all shapes in grid order
        found = False
        for shape_idx, shape in enumerate(shapes):
            for r in range(n):
                for c in range(m):
                    if can_place(r, c, shape):
                        placement[shape_idx].append((r, c))
                        found = True

                        update(r, c, shape, chr(ord('A') + (len(placed) - 1)))
                        backtrack()
                        revert(update(r, c, shape, chr(65 + len(placed) - 1), shape))

                    break
                if not found: 
                    break

        return False

    better = False
    current_placements = []

    def try_solve(idx, prev_idx=-1):
        nonlocal better, current_placements

        if len(current_placements) + (n * m - sum(cell == '_' for row in grid for cell in row)) // 5 <= placement_count:
            return

        # Try placing more shapes
        if idx < placement_count:
            shape_idx = idx % len(shapes)
            for r in range(n - 3):
                for c in range(m - 1):
                    if not can_place(r, c, shapes[shape_idx]):
                        continue

                    # Mark position
                    updated = place(r, c, shapes[shape_idx], chr(ord('A') + placement_count))
                    if updated:
                        try_solve(idx + 1, shape_idx)
                        revert(r, c, shapes[shape_idx])
                        placement_count -= 1                    

        return False


