        return str(a[0] % MOD)

    # Compute factorials and modular inverses for binomial coefficients
    MAX = n + 1
    fact = [1] * MAX
    inv = [1] * MAX

    for i in range(1, MAX):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[MAX - 1] = pow(fact[MAX - 1], MOD - 2, MOD)
    for i in range(MAX - 2, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def nCr(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % MOD * inv[n - k] % MOD

    result = 0
    for i in range(n):
        coef = nCr(n - 1, i)
        # Apply alternating sign pattern
        if (n - 1 - i) % 2 == 0:
            coef = coef
        else:
            coef = (MOD - coef) % MOD
        result = (result + coef * (a[i] % MOD)) % MOD

    return str(result)

