def solution(input_str):
    parts = input_str.strip().split()
    max_x = int(parts[0])
    max_y = int(parts[1])
    w = int(parts[2])

    memo = {}
    def rev(x):
        if x not in memo:
            memo[x] = int(str(x)[::-1])
        return memo[x]

    best_x, best_y = -1, -1
    min_prod = float('inf')

    for x in range(1, max_x + 1):
        # If x alone exceeds min_prod, skip forward
        if min_prod <= x:
            break

        for y in range(1, max_y + 1):
            prod = x * y
            if prod >= min_prod:
                break

            # Count lucky tickets
            cnt = 0
            for a in range(1, x + 1):
                ra = rev(a)
                for b in range(1, y + 1):
                    if a * b == ra * rev(b):
                        cnt += 1

            if cnt >= w:
                min_prod = prod
                best_x, best_y = x, y

    if best_x != -1:
        return f"{best_x} {best_y}\n"
    else:
        return "-1"

import sys
from functools import lru_cache

sys.setrecursionlimit(50000)

def solution(input_str):
    line = input_str.strip()
    if not line:
        return "Missing\n\n"

    a, b, n = map(int, line.split())

    # Special case: when a = 1, a^b = 1 for any b
    # Since n >= 2, the game never ends (infinite game)
    if a == 1:
        return "Missing\n\n"

    @lru_cache(maxsize=1000000)
    def can_force_win(a_val, b_val):
        """
        Returns True if the current player can force a win from state (a_val, b_val)
        A player wins if they can make a move that forces the opponent to lose
        """
        # Check if we've already reached the threshold (previous player lost)
        if a_val ** b_val >= n:
            return False

        win_possible = False

        # Option 1: Add a box
        new_a = a_val + 1
        if new_a ** b_val >= n:
            # This move causes the opponent to lose immediately
            win_possible = True
        else:
            # Opponent moves from new state; if opponent can't win, this is winning for us
            if not can_force_win(new_a, b_val):
                win_possible = True

        # Option 2: Add an item (only check if not already winning)
        if not win_possible:
            new_b = b_val + 1
            if a_val ** new_b >= n:
                win_possible = True
            else:
                if not can_force_win(a_val, new_b):
                    win_possible = True

        return win_possible

    if can_force_win(a, b):
        return "Stas\n\n"
    else:
        return "Masha\n\n"


if __name__ == "__main__":
    import sys
    input_data = sys.stdin.read()
    if input_data.strip():
        result = solution(input_data)
        print(result)

