# Your solution code here
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    best_assignment = None
    best_cost = float('inf')

    def is_harmony(assignment):
        for i in range(len(assignment)):
            for j in range(i + 1, len(assignment)):
                if assignment[i] != 1 and assignment[j] != 1 and assignment[i] != assignment[j]:
                    if gcd(assignment[i], assignment[j]) != 1:
                        return False
        return True

    def backtrack(idx, current_assignment):
        nonlocal best_assignment, best_cost

        # Calculate minimum possible cost from this point
        if idx == n:
            # Validate harmony and compute cost (assuming minimizing sum of gcd(a_i, b_i))
            cost = 0
            for i in range(n):
                cost += gcd(a[i], current_assignment[i])

            if cost < best_cost:
                best_cost = cost
                best_assignment = list(current_assignment)
            return

        # Pruning: if minimum possible remaining + current exceeds best
        if best_assignment is not None:
            min_remaining = 0
            for i in range(idx, n):
                # Minimum gcd for position i is 1 (using b[i]=1)
                min_remaining += 1

            if current_cost + min_remaining >= best_cost:
                if best_assignment is not None:
                    return

        # Try values from 1 upward (greedy: smaller values first)
        for val in range(1, 200):
            # Check harmony constraint
            valid = True
            for prev in current_assignment:
                if prev != 1 and val != 1:
                    if prev == val and val != 1:
                        valid = False
                    elif gcd(prev, val) != 1:
                        valid = False

            if valid:
                current_assignment.append(val)
                current_cost += gcd(a[idx], val)
                backtrack(idx + 1, current_assignment)
                current_assignment.pop()
                current_cost -= gcd(a[idx], val)

            # Early termination if we found a valid assignment
            if current_assignment and current_assignment[-1] == 1:
                # Try remaining values
                for val in range(val + 1, 200):
                    valid = True
                    for prev in current_assignment:
                        if prev != 1 and val != 1:
                            if prev == val and val != 1:
                                valid = False
                            elif gcd(prev, val) != 1:
                                valid = False
                    if valid:
                        current_assignment.append(val)
                        current_cost += gcd(a[idx], val)
                        backtrack(idx + 1, current_assignment)
                        current_assignment.pop()
                        current_cost -= gcd(a[idx], val)

    backtrack(0, [])

    result = ''
    if best_assignment is not None:
        result = ' '.join(map(str, best_assignment)) + '\n'

    return result

# Test with provided examples
