def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v = map(int, lines[i + 1].split())
        adj[u].append(v)
        adj[v].append(u)

    a = list(map(int, lines[m + 1].split()))

    x = [0] * (n + 1)

    def compute_final():
        result = [0] * (n + 1)
        for i in range(1, n + 1):
            val = x[i]
            for neighbor in adj[i]:
                val += x[neighbor]
            result[i] = val
        return result

    def solve(idx):
        if idx == n + 1:
            final = compute_final()
            return all(final[i] != a[i - 1] for i in range(1, n + 1))

        x[idx] = 1
        if solve(idx + 1):
            return True
        x[idx] = 0
        if solve(idx + 1):
            return True

        return False

    if solve(1):
        result = [i for i in range(1, n + 1) if x[i] == 1]
        print(len(result))
        if result:
            print(' '.join(map(str, result)))
    else:
        print(-1)

