from functools import lru_cache

def analyze_game(s, e):
    """Check if first player can force a win given start value s and limit e."""
    @lru_cache(maxsize=None)
    def can_force_win(val):
        if val > e:
            return False

        for mv in [val * 2, val + 1]:
            if mv > e:
                continue
            # If after our move, the opponent cannot force a win, we win
            if not can_force_win(mv):
                return True

        return False

    return can_force_win(s)

def solution(input_str):
    """Main solution function."""
    lines = input_str.strip().split('\n')
    t = int(lines[0])

    lee_always_win = False
    lee_always_lose = False

    lee_starts = True  # Lee starts the first round

    for i in range(1, t + 1):
        s, e = map(int, lines[i].split())
        first_wins = analyze_game(s, e)

        if lee_starts:
            if first_wins:
                lee_always_win = True
                lee_always_lose = False
            else:
                lee_always_win = False
                lee_always_lose = True
        else:
            if first_wins:
                lee_always_win = False
                lee_always_lose = True
            else:
                lee_always_win = True
                lee_always_lose = False

        lee_starts = first_wins

    return f"{lee_always_win} {lee_always_lose}"

