def solution(n_str, capacities_str):
    n = int(n_str)
    if capacities_str.strip():
        a = list(map(int, capacities_str.split()))
    else:
        a = []

    s = sum(a)
    if not a:
        return "0\n"

    m = min(a)
    count_min = a.count(m)

    # Check if the minimum appears exactly once (isolated minimum)
    isolated = False
    for i in range(len(a)):
        if a[i] == m:
            if i == 0:
                isolated = (i + 1 == len(a) or a[i + 1] != m)
            elif i == len(a) - 1:
                isolated = (a[i - 1] != m)
            else:
                isolated = (a[i - 1] != m) and (a[i + 1] != m)

    if isolated:
        s -= 1

    return f"{s}\n"


