import sys

def solve():
    data = read_input()
    t = int(data[0])
    cases = []
    idx = 1
    for _ in range(t):
        n = int(data[idx])
        idx += 1
        p = list(map(int, data[idx:n+idx]))
        idx += n
        cases.append((n, p))

    output_lines = []
    for n, p in cases:
        result = solve_case(n, p)
        output_lines.append(result)

    print('\n'.join(output_lines))

def solve_case(n, p):
    # Try multiple approaches
    result = try_approach(n, p)
    if result is None:
        try:
            result = try_greedy(n, p)
        except:
            pass
    if result is None:
        return "NO"
    return f"YES\n{result}"

def try_approach(n, p):
    # Approach 1: Greedy - try to illuminate from each side
    ans = [''] * n

    # Try to process from left to right
    # For each lantern, try to illuminate it from the left or right
    # We can use a flow-like approach or greedy matching

    # Build adjacency: who can illuminate whom
    # Lantern i can illuminate:
    # - j in [max(0, i - p[i]), i-1] if pointing left
    # - j in [i+1, min(n-1, i + p[i])] if pointing right

    # Greedy strategy:
    # Try to make a direction valid for all lanterns
    # First, try a pattern where we alternate L/R

    # Approach: For each position, try to determine if it should point L or R
    # based on whether it can be illuminated

    # Let's try: pick direction that maximizes illumination of currently unilluminated lanterns

    # Simpler approach: use DP or greedy matching
    # For each lantern, check if it can be illuminated from left or right

    # Create a solution by trying different patterns

    # Pattern 1: try to make it so even positions point R, odd positions point L
    ans = [''] * n
    for i in range(n):
        if i % 2 == 0:
            ans[i] = 'R'
        else:
            ans[i] = 'L'

    if check_solution(n, p, ans):
        return ''.join(ans)

    # Pattern 2: reverse
    ans = [''] * n
    for i in range(n):
        if i % 2 == 0:
            ans[i] = 'L'
        else:
            ans[i] = 'R'

    if check_solution(n, p, ans):
        return ''.join(ans)

    # Pattern 3: greedy directional assignment
    return greedy_solve(n, p)

def check_solution(n, p, ans):
    # Check if each lantern is illuminated
    # ans[i] is 'L' if lantern i points left, 'R' if right

    # For each lantern i, check if it's illuminated by some other lantern
    illuminated = [False] * n

    for i in range(n):
        if ans[i] == 'L':
            # Points left: can illuminate [i - 1, max(0, i - p[i])]
            reach_left = min(i - 1, max(0, i - p[i]))
            for j in range(i):
                if j >= reach_left:
                    continue  # j is not reachable
                    # Actually, we need to check if j can illuminate i
            # From left to right, j (where j < i) illuminates i if j points R and i is in [j+1, j+p[j]]
            # From right to left, j (where j > i) illuminates i if j points L and i is in [j-p[j], j-1]

        # Check if i is illuminated by someone to its left
        for j in range(i):
            if ans[j] == 'R' and j + p[j] >= i:
                illuminated[i] = True
                break

        if not illuminated[i]:
            # Check if i is illuminated by someone to its right
            for j in range(i + 1, n):
                if ans[j] == 'L' and j - p[j] <= i:
                    illuminated[i] = True
                    break

        if not illuminated[i]:
            return False

    return True

def greedy_solve(n, p):
    # Greedy approach: try to make a valid assignment

    # Key insight: process lanterns and decide directions as we go
    # Try two greedy strategies

    # Strategy 1: For each lantern from left to right, 
    # try to make it point R if it can illuminate needed ones,
    # otherwise point L

    ans = [''] * n

    def greedy_help(n, p):
        # Greedy with clean implementation
        # For each lantern, decide direction based on illumination needs
        # Try left-to-right, then right-to-left

        # Method: try to match each lantern with a lantern that can illuminate it

        # Process from left to right
        # Try to make current lantern illuminate others, or be illuminated

        covered = [False] * n
        for i in range(n):
            # Find if there's lantern to left that can illuminate i
            can_be_illuminated = False
            for j in range(i):
                if j + p[j] >= i:
                    can_be_illuminated = True
                    break

            # Find if there's lantern to right that can illuminate i
            for j in range(i + 1, n):
                if j - p[j] <= i:
                    can_be_illuminated = True
                    break

            if not can_be_illuminated:
                return None  # Cannot be illuminated

        # All can potentially be illuminated from theoretical perspective
        # Now construct actual assignment

        # Try alternating pattern
        ans = [''] * n
        for i in range(n):
            if i % 2 == 0:
                ans[i] = 'R'
            else:
                ans[i] = 'L'

        if all_illuminated(n, p, ans):
            return ''.join(ans)

        # Try other patterns
        ans = [''] * n
        for i in range(n):
            if i % 2 == 1:
                ans[i] = 'L'
            else:
                ans[i] = 'R'

        if all_illuminated(n, p, ans):
            return ''.join(ans)

        return None

    ans = greedy_help(n, p)
    return ans

def all_illuminated(n, p, ans):
    covered = [False] * n
    for i in range(n):
        # Check left
        for j in range(i):
            if ans[j] == 'R' and j + p[j] >= i:
                covered[i] = True
                break
        if not covered[i]:
            # Check right
            for j in range(i + 1, n):
                if ans[j] == 'L' and j - p[j] <= i:
                    covered[i] = True
                    break
        if not covered[i]:
            return False
    return True

