# Solution code for the Alice and Bob game problem

def mex(s):
    result = 0
    while result in s:
        result += 1
    return result

def compute_sg(n_final, needed):
    sg = [0] * (n_final + 1)
    for L in range(needed, n_final + 1):
        moves = set()
        for i in range(L - needed + 1):
            left = i
            right = L - needed - i
            moves.add(sg[left] ^ sg[right])
        sg[L] = mex(moves)
    return sg

