    max_len = 0
    for _, _, s in queries:
        # Replace X with space, count consecutive periods
        for seg in s.split('X'):
            max_len = max(max_len, len(seg) if seg else a)

    if max_len == 0:
        max_len = max((a + b) // 2, 1) * 2

    # Compute SG tables
    sg_A = compute_sg(max_len, 300005)
    sg_B = compute_sg(max_len, 300005)

    for a, b, s in queries:
        # Find all consecutive dot segments
        segments = []
        n = len(s)
        i = 0
        while i < n:
            if s[i] == '.':
                j = i
                while j < n and s[j] == '.':
                    j += 1
                segments.append(j - i)
                i = j
            else:
                i += 1

        # Alice needs length >= a, Bob needs length >= b
        xor_sum = 0
        for length in segments:
            if length >= a:
                xor_sum ^= sg_A[length]
            if length >= b:
                xor_sum ^= sg_B[length]

        if xor_sum > 0:
            results.append('YES')
        else:
            results.append('NO')

    return '\n'.join(results)

