# Helper: find connected components
def get_components(edges: List[List[int]]) -> int:
    if not edges:
        return 0
    adj = {}
    for u, v in edges:
        if u not in adj: adj[u] = set()
        if v not in adj: adj[v] = set()
        adj[u].add(v)
        adj[v].add(u)

    visited = set()
    count = 0
    for start in adj:
        if start not in visited:
            count += 1
            queue = [start]
            visited.add(start)
            while queue:
                curr = queue.pop()
                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
    return count

def solve(n: int, A: str, B: str) -> int:
    edges = []
    for i in range(n):
        if A[i] != B[i]:
            edges.append([ord(A[i]) - ord('a'), ord(B[i]) - ord('a')])

    if not edges:
        return 0

    has_self_loop = any(u == v for u, v in edges)

    return 1 if has_self_loop else get_components([(u, v) for u, v in edges])

