    def solve_for_outcome(a, b, a_wins, b_wins):
        """Try to find valid set scores for a given match outcome"""
        total_sets = a_wins + b_wins

        # Check all permutations of who wins which sets
        # Positions of A's wins
        from itertools import combinations
        positions = range(total_sets)
        a_pos_list = combinations(positions, a_wins)

        for a_positions in a_pos_list:
            sets = [None] * total_sets
            for pos in a_positions:
                sets[pos] = 'A'  # Will be determined later
            for i in range(total_sets):
                if sets[i] != 'A':
                    sets[i] = 'B'  # B wins here

            # DFS to fill in the scores
            temp_sets = [None] * total_sets  # To store (a_score, b_score)

            def dfs(rem_a, rem_b, idx):
                if idx == total_sets:
                    if rem_a == 0 and rem_b == 0:
                        return temp_sets[:]
                    return None

                if temp_sets[idx] is None:
                    is_A_win = (sets[idx] == 'A')

