                                    del temp_sets[idx]

                else:
                    return dfs(rem_a, rem_b, idx + 1)

            result = dfs(a, b, 0)
            if result is not None:
                return result
        return None

    def try_matches(a, b):
        """Try outcomes in order: 3:0, 3:1, 3:2"""
