    n, k = map(int, lines[0].split())
    s = lines[1].strip()

    if n == 0:
        return "NO\n"

    # dp[bal] = (prev_bal, choice) where bal is balance after current position
    # prev_bal is the balance before this position, choice is what we did
    dp = {0: (None, None)}  # Initial state: balance 0 before any games

    for i in range(n):
        new_dp = {}
        char = s[i]

        # Determine which actions are allowed
        if char == '?':
            choices = ['W', 'L', 'D']
        elif char == 'W':
            choices = ['W']
        elif char == 'L':
            choices = ['L']
        else:  # 'D'
            choices = ['D']

        for bal, (prev_bal, _) in dp.items():
            for action in choices:
                if action == 'W':
                    new_bal = bal + 1
                elif action == 'L':
                    new_bal = bal - 1
                else:  # 'D'
                    new_bal = bal

                # Check if valid
                if i == n - 1:
                    valid = abs(new_bal) == k
                else:
                    valid = abs(new_bal) < k

                if valid:
                    new_dp[new_bal] = (bal, action)

        dp = new_dp

        if not dp:
            return "NO\n"

    # Find any valid end state (must have |balance| == k)
    final_bal = None
    for bal in dp:
        if abs(bal) == k:
            final_bal = bal
            break

    if final_bal is None:
        return "NO\n"

    # Reconstruct the sequence
    result = []
    cur = final_bal

    for i in range(n - 1, -1, -1):
        prev_bal, action = dp[cur]
        result.append(action)

        # To go backward, undo the action
        if action == 'W':
            cur = prev_bal - 1
        elif action == 'L':
            cur = prev_bal + 1
        else:  # 'D'
            cur = prev_bal  # D doesn't change balance

    return ''.join(result[::-1]) + '\n'

