import sys
from itertools import combinations

def solution(input_string: str) -> str:
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    constraints = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s = parts[0]
        c = int(parts[1])
        constraints.append((s, c))

    s0, c0 = constraints[0]
    count = 0

    for positions in combinations(range(n), c0):
        # Create position set for O(1) lookup
        pos_set = set(positions)
        candidate = [0] * n

        # Build candidate: match s0 at positions, flip at others
        for j in range(n):
            candidate[j] = int(s0[j]) if j in pos_set else 1 - int(s0[j])

        # Check if candidate satisfies all other constraints
        valid = True
        for s, c in constraints[1:]:
            actual_c = 0
            for j in range(n):
                if candidate[j] == int(s[j]):
                    actual_c += 1
            if actual_c != c:
                valid = False
                break

        if valid:
            count += 1

    return str(count)


